// The two declarations that describe the enriched release notes body
// .github/tools/src/scripts/release-notes.ts composes. No release command reads them.

// HIGHLIGHTS_HEADING opens the agent's section of an enriched body, the way
// GitHub's own notes open with "## What's Changed". release-notes.ts adds it
// when it composes the body from its own copy of the heading. The adapter
// tests in release-notes.test.ts (Windows and POSIX) compare the body the
// script writes, byte for byte, with one built from this copy, and the
// script's own tests pin its copy to the literal heading.
export const HIGHLIGHTS_HEADING = "## 🌟 Release Highlights\n\n";

// FOOTER_PATTERN recognizes the provenance line release-notes.ts appends,
// whatever run wrote it. The line names its own run, so a byte-exact
// comparison would read a second dispatch's release as hand-written notes and
// refuse it. The engine and model are the workflow's own literals and are
// deliberately not repeated here: the workflow already writes them twice, in
// its engine block and in NOTES_ENGINE and NOTES_MODEL, which a test compares,
// so a third copy would be one more to drift.
export const FOOTER_PATTERN =
  /^> Generated by \[Agentics release\]\(\S+\/actions\/runs\/[1-9][0-9]*\) · [^\n·]+ · [^\n·]+$/;
